// Starts `next dev` over HTTPS using the certificates trusted by Office,
// generated by `pnpm certs:install` (office-addin-dev-certs).
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const certDir = join(homedir(), ".office-addin-dev-certs");
const key = join(certDir, "localhost.key");
const cert = join(certDir, "localhost.crt");
const ca = join(certDir, "ca.crt");

if (!existsSync(key) || !existsSync(cert)) {
  console.error(
    "Office dev certificates not found. Run `pnpm certs:install` first.",
  );
  process.exit(1);
}

const child = spawn(
  "next",
  [
    "dev",
    "--experimental-https",
    "--experimental-https-key",
    key,
    "--experimental-https-cert",
    cert,
    "--experimental-https-ca",
    ca,
  ],
  { stdio: "inherit", shell: true },
);

child.on("exit", (code) => process.exit(code ?? 0));
